<script setup>
import { onMounted, reactive, ref } from 'vue'
import api from '@/api'
import { currency, dateTime, statusMap } from '@/utils/format'
const loading=ref(false);const result=reactive({items:[],total:0});const params=reactive({keyword:'',status_filter:'',page:1,page_size:20});const detail=ref(false);const current=ref(null)
const load=async()=>{loading.value=true;try{Object.assign(result,await api.get('/admin/orders',{params}))}finally{loading.value=false}}
const open=(row)=>{current.value=row;detail.value=true}
onMounted(load)
</script>
<template><div><div class="admin-filters"><el-input v-model="params.keyword" clearable placeholder="搜索订单号" @keyup.enter="load"><template #prefix><el-icon><Search/></el-icon></template></el-input><el-select v-model="params.status_filter" clearable placeholder="订单状态" style="width:160px"><el-option v-for="key in ['pending','paid','meeting','completed','cancelled','refunding','disputed']" :key="key" :label="statusMap[key][0]" :value="key"/></el-select><el-button type="success" @click="params.page=1;load()">查询</el-button><el-button @click="Object.assign(params,{keyword:'',status_filter:'',page:1});load()">重置</el-button><span class="filter-count">共 {{result.total}} 笔订单</span></div><section class="admin-card"><el-table v-loading="loading" :data="result.items"><el-table-column label="订单 / 商品" min-width="300"><template #default="{row}"><div class="table-product"><img :src="row.product?.images?.[0]"/><div><strong>{{row.product?.title}}</strong><small>{{row.order_no}}</small></div></div></template></el-table-column><el-table-column label="买家" prop="buyer.nickname"/><el-table-column label="卖家" prop="seller.nickname"/><el-table-column label="金额"><template #default="{row}"><strong class="price-text">{{currency(row.amount)}}</strong></template></el-table-column><el-table-column label="见面地点" min-width="170" prop="meetup_place"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="statusMap[row.status]?.[1]">{{statusMap[row.status]?.[0]}}</el-tag></template></el-table-column><el-table-column label="下单时间" width="160"><template #default="{row}">{{dateTime(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="{row}"><el-button size="small" @click="open(row)">查看详情</el-button></template></el-table-column></el-table><div class="pagination-row"><el-pagination v-model:current-page="params.page" background layout="total,prev,pager,next" :total="result.total" :page-size="params.page_size" @current-change="load"/></div></section><el-drawer v-model="detail" title="订单详情" size="470px"><template v-if="current"><div class="drawer-product"><img :src="current.product?.images?.[0]"/><div><strong>{{current.product?.title}}</strong><span>{{currency(current.amount)}}</span></div></div><el-descriptions :column="1" border><el-descriptions-item label="订单编号">{{current.order_no}}</el-descriptions-item><el-descriptions-item label="订单状态"><el-tag :type="statusMap[current.status]?.[1]">{{statusMap[current.status]?.[0]}}</el-tag></el-descriptions-item><el-descriptions-item label="买家">{{current.buyer?.nickname}}（{{current.buyer?.campus}}）</el-descriptions-item><el-descriptions-item label="卖家">{{current.seller?.nickname}}（{{current.seller?.campus}}）</el-descriptions-item><el-descriptions-item label="见面地点">{{current.meetup_place}}</el-descriptions-item><el-descriptions-item label="买家留言">{{current.buyer_note||'无'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{dateTime(current.created_at)}}</el-descriptions-item><el-descriptions-item label="付款时间">{{dateTime(current.paid_at)}}</el-descriptions-item><el-descriptions-item v-if="current.cancel_reason" label="取消/争议原因">{{current.cancel_reason}}</el-descriptions-item></el-descriptions><div class="risk-tip"><el-icon><Warning/></el-icon><div><strong>订单干预需谨慎</strong><p>如遇争议，请先核对聊天记录、商品描述和双方举证。</p></div></div></template></el-drawer></div></template>
<style scoped>.filter-count{margin-left:auto;color:#818a84;font-size:12px}.price-text{color:#df572d}.drawer-product{display:flex;gap:13px;align-items:center;padding:15px;margin-bottom:20px;border-radius:9px;background:#f4f7f3}.drawer-product img{width:90px;height:76px;object-fit:cover;border-radius:7px}.drawer-product strong,.drawer-product span{display:block}.drawer-product span{margin-top:8px;color:#dd572e;font-size:22px;font-weight:700}.risk-tip{display:flex;gap:10px;margin-top:20px;padding:15px;border-radius:8px;background:#fff7ed;color:#b66b32}.risk-tip p{margin-top:4px;color:#8a7768;font-size:12px}</style>

